function speechButtonLabel(button,playing){button.textContent=playing?(button.dataset.playingLabel||'Stop'):(button.dataset.idleLabel||'Listen');button.setAttribute('aria-label',playing?'Stop reading Paige aloud':'Read Paige aloud');button.setAttribute('aria-pressed',String(playing))}
