function populateVoices(){const select=$('#voiceURI');if(!select||!speechSupported)return;const chosen=select.value||settings.voiceURI||'';select.replaceChildren(new Option('System default',''));const voices=availableVoices();voices.sort((a,b)=>(Number(/^en-AU$/i.test(b.lang))-Number(/^en-AU$/i.test(a.lang)))||a.lang.localeCompare(b.lang)||a.name.localeCompare(b.name)).forEach(v=>select.add(new Option(v.name+' ('+v.lang+')',v.voiceURI)));select.value=[...select.options].some(o=>o.value===chosen)?chosen:''}
