function addBubble(role,text,index){const el=document.createElement('div');el.className='message '+role;el.innerHTML=role==='assistant'?'<div class="message-header"><img src="./assets/paige-avatar.webp" alt="" width="34" height="34"><span>Paige</span></div><div class="message-body">'+esc(text)+'</div>':esc(text);if(role==='assistant'&&text!=='Paige is thinking…'){const actions=document.createElement('div');actions.className='message-actions';actions.innerHTML=(speechSupported?'<button type="button" data-action="play" aria-label="Read Paige aloud" aria-pressed="false">Listen</button>':'')+(Number.isInteger(index)?'<button type="button" data-action="copy">Copy</button><button type="button" data-action="regenerate">Regenerate</button><button type="button" data-action="continue">Continue</button>':'');actions.onclick=async e=>{const a=e.target.dataset.action;if(a==='play')speakText(text,e.target);if(a==='copy'){await navigator.clipboard?.writeText(text);e.target.textContent='Copied';setTimeout(()=>e.target.textContent='Copy',900)}if(a==='regenerate')regenerate(index);if(a==='continue')continueAnswer()};el.append(actions)}chat.append(el);return el}
