  const res=await fetch(settings.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:legacyMessage,model:settings.model,temperature:Number(settings.temperature),system:systemMessage()+"\n\nRules for this turn (take priority over background and examples):\n"+turnRules+arrivalRules+quietRules+continuationRules,messages:outbound})});
  let data={};try{data=await res.json()}catch{}
  if(!res.ok)throw new Error(data?.error||data?.message||`Request failed (${res.status})`);
  const text=data?.reply||data?.text||data?.message||data?.choices?.[0]?.message?.content;
  if(!text)throw new Error('The AI backend returned no message.');
