async function regenerate(index){if(busy)return;const prior=messages.slice(0,index);if(prior.at(-1)?.role!=='user')return;messages=prior;save();render();await run()}
async function continueAnswer(){if(busy)return;messages.push({role:'user',content:'Continue directly after your last reply. Add a new beat in the scene as Paige, without restarting the arrival or speaking or acting for me.',at:Date.now(),hidden:true});save();render();await run()}
